            "text": "本法所稱有價證券，指政府債券、公司股票、公司債券及經主管機關核定之其他有價證券。\r\n新股認購權利證書、新股權利證書及前項各種有價證券之價款繳納憑證或表明其權利之證書，視為有價證券。\r\n前二項規定之有價證券，未印製表示其權利之實體有價證券者，亦視為有價證券。"
