            "text": "凡依本法公開募集及發行有價證券之公司，其全體董事及監察人二者所持有記名股票之股份總額，各不得少於公司已發行股份總額一定之成數。\r\n前項董事、監察人股權成數及查核實施規則，由主管機關以命令定之。"
