            "type": "article",
            "no": "第 161 條",
            "text": "主管機關為保護公益或投資人利益，得以命令通知證券交易所變更其章程、業務規則、營業細則、受託契約準則及其他章則或停止、禁止、變更、撤銷其決議案或處分。"
