            "no": "第 181-2 條",
            "text": "經主管機關依第十四條之二第一項但書規定要求設置獨立董事、依第十四條之四第一項但書規定設置審計委員會，或第二十六條之三施行時依同條第六項規定董事、監察人應當然解任者，得自現任董事或監察人任期屆滿時，始適用之。"
