            "no": "第 183 條",
            "text": "本法施行日期，除中華民國八十六年五月七日、八十九年七月十九日修正公布之第五十四條、第九十五條及第一百二十八條，自九十年一月十五日施行；九十五年一月十一日修正公布之第十四條之二至第十四條之五、第二十六條之三，自九十六年一月一日施行；九十五年五月三十日修正公布條文，自九十五年七月一日施行；九十八年六月十日修正公布條文，自九十八年十一月二十三日施行；九十九年六月二日修正公布之第三十六條，自一百零一年一月一日施行；一百零一年一月四日修正公布之第三十六條第一項第二款，自一百零二會計年度施行外，自公布日施行。\r\n本法中華民國一百十二年四月二十一日修正之第四十三條之一，自公布後一年施行。"
