            "no": "第 8-1 條",
            "text": "本法第四十三條之七所定一般性廣告或公開勸誘之行為，係指以公告、廣告、廣播、電傳視訊、網際網路、信函、電話、拜訪、詢問、發表會、說明會或其他方式，向本法第四十三條之六第一項以外之非特定人為要約或勸誘之行為。"
