            "text": "證券投資信託事業兼營期貨信託事業，未發行期貨信託基金而運用證券投資信託基金從事證券相關商品交易超過本會所定一定比率應申請核准者，其投資研究部門主管、該基金經理人及至少一名內部稽核人員應具備期貨商負責人及業務員管理規則第五條所定資格條件。"
