            "type": "article",
            "no": "第 15 條",
            "text": "總代理人如發現銷售機構代理境外基金之募集及銷售，或參與證券商辦理境外指數股票型基金之申購與買回，違反法令、契約、逾越授權範圍或損害投資人權益之情事，應立即督促其改善，並立即通知本會。\r\n總代理人、銷售機構、參與證券商及其董事、監察人、經理人或受僱人因故意、過失或違反契約或法令規定，致損害投資人之權益者，應負損害賠償責任。"
